QString text(const Json& j){return j.is_null()?QString::fromUtf8("未知"):QString::fromStdString(j.is_string()?j.get<std::string>():j.dump());}
QString value(const Json& j){return j.is_number_float()?QString::number(j.get<double>(),'g',8):text(j);}
QString joined(const Json& a){QStringList values;for(const auto& n:a)values<<text(n);return values.join(", ");}
Json numbers(QString input,bool integers=false){input.replace(QString::fromUtf8("，"),",");Json values=Json::array();for(const auto& token:input.split(QRegularExpression("[,\\s]+"),Qt::SkipEmptyParts)){bool ok=false;if(integers){auto n=token.toLongLong(&ok);if(!ok)throw std::runtime_error("Integer history budgets required");values.push_back(n);}else {double n=token.toDouble(&ok);if(!ok||!std::isfinite(n))throw std::runtime_error("Finite numeric values required");values.push_back(n);}}return values;}
void fill(QTableWidget* table,const QStringList& values){int row=table->rowCount();table->insertRow(row);for(int i=0;i<values.size();++i)table->setItem(row,i,new QTableWidgetItem(values[i]));}
QTableWidget* table(QWidget* parent,const char* name,const QStringList& headers){auto* t=new QTableWidget(0,headers.size(),parent);t->setObjectName(name);t->setHorizontalHeaderLabels(headers);t->setEditTriggers(QAbstractItemView::NoEditTriggers);t->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);t->setSelectionBehavior(QAbstractItemView::SelectRows);return t;}
