        auto* outer=new QVBoxLayout(this);outer->setContentsMargins(0,0,0,0);auto* scroll=new QScrollArea(this);scroll->setObjectName("spaceradPartitionScroll");scroll->setWidgetResizable(true);auto* body=new QWidget(scroll);scroll->setWidget(body);outer->addWidget(scroll);auto* layout=new QVBoxLayout(body);
        auto* help=new QLabel(tr("工程快照：%1。每种粒子完整覆盖原能域，保持谱形与物理暴露；粗细分层使用相同逐粒子预算和不同种子。原工程与已有结果保留。").arg(QString::fromStdString(p.name)),body);help->setWordWrap(true);help->setTextFormat(Qt::PlainText);layout->addWidget(help);
        editor=new QGroupBox(tr("固定预算研究计划"),body);auto* form=new QFormLayout(editor);
        shell=new QComboBox(editor);shell->setObjectName("spaceradPartitionShell");for(const auto& v:p.volumes)if(v.shape=="box"&&v.wall>0&&!v.sensitive)shell->addItem(QString::fromStdString(v.id));form->addRow(tr("保持内腔的非敏感盒壳"),shell);
        thickness=new QLineEdit("0.8, 2",editor);thickness->setObjectName("spaceradPartitionThicknesses");if(shell->count())for(const auto& v:p.volumes)if(QString::fromStdString(v.id)==shell->currentText())thickness->setText(QString::number(v.wall,'g',17)+", "+QString::number(v.wall+1.2,'g',17));form->addRow(tr("壁厚 mm（2–64 项，严格递增）"),thickness);
        bands=new QTableWidget(0,5,editor);bands->setObjectName("spaceradPartitionBands");bands->setHorizontalHeaderLabels({tr("粒子"),tr("粗分层切点 MeV"),tr("粗分层逐段历史"),tr("细分层切点 MeV"),tr("细分层逐段历史")});bands->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);bands->setMinimumHeight(110);bands->setMaximumHeight(170);form->addRow(bands);
        auto* options=new QHBoxLayout;replicas=new QSpinBox(editor);replicas->setObjectName("spaceradPartitionReplicas");replicas->setRange(2,4);hits=new QSpinBox(editor);hits->setObjectName("spaceradPartitionMinHits");hits->setRange(2,100000000);rse=new QLineEdit(editor);rse->setObjectName("spaceradPartitionMaxRse");confidence=new QLineEdit(editor);confidence->setObjectName("spaceradPartitionConfidence");options->addWidget(new QLabel(tr("每套重复"),editor));options->addWidget(replicas);options->addWidget(new QLabel(tr("每段最少沉积历史"),editor));options->addWidget(hits);options->addWidget(new QLabel(tr("最大 RSE"),editor));options->addWidget(rse);options->addWidget(new QLabel(tr("概率族覆盖率"),editor));options->addWidget(confidence);form->addRow(options);
        output=new QLineEdit(editor);output->setObjectName("spaceradPartitionOutput");auto* outRow=new QHBoxLayout;outRow->addWidget(output);auto* fresh=new QPushButton(tr("新任务目录"),editor);outRow->addWidget(fresh);form->addRow(tr("输出目录"),outRow);
        preview=new QLabel(editor);preview->setObjectName("spaceradPartitionPreview");preview->setWordWrap(true);form->addRow(preview);layout->addWidget(editor);
        auto* controls=new QHBoxLayout;auto add=[&](const QString& title,const char* name){auto* b=new QPushButton(title,body);b->setObjectName(name);controls->addWidget(b);return b;};run=add(tr("开始全谱研究"),"spaceradPartitionRun");cancel=add(tr("取消"),"spaceradPartitionCancel");open=add(tr("打开历史研究"),"spaceradPartitionOpen");saveConfig=add(tr("保存研究配置"),"spaceradPartitionSaveConfig");importConfig=add(tr("导入研究配置"),"spaceradPartitionImportConfig");cancel->setEnabled(false);controls->addStretch();layout->addLayout(controls);
        progress=new QProgressBar(body);progress->setObjectName("spaceradPartitionProgress");progress->setRange(0,1000);layout->addWidget(progress);status=new QLabel(tr("待运行。"),body);status->setObjectName("spaceradPartitionStatus");status->setWordWrap(true);status->setTextFormat(Qt::PlainText);layout->addWidget(status);
        auto* caution=new QLabel(tr("改变分层检验抽样稳定性，不是确定性网格收敛。每段零沉积时，全谱误差保留未知；零事件概率上限不是剂量上限。经验筛查不等于独立物理验证。取消保留子任务档案，不接收整组结果。表内显示 8 位有效数字，导出保留完整精度。"),body);caution->setWordWrap(true);layout->addWidget(caution);
        estimates=table(body,"spaceradPartitionEstimates",{tr("壁厚 mm"),tr("靶区"),tr("重复"),"TID Gy",tr("观测 SE Gy"),tr("全谱 RSE"),tr("零命中段"),tr("能段支持")});estimates->setMinimumHeight(180);layout->addWidget(estimates);
        layout->addWidget(new QLabel(tr("选中一行查看逐能段沉积支持与同一靶区的重复比较"),body));components=table(body,"spaceradPartitionComponents",{tr("粒子"),tr("能域 MeV"),tr("历史"),tr("非零沉积"),"TID Gy","RSE",tr("沉积 ESS"),tr("零事件概率上限"),tr("支持")});components->setMinimumHeight(160);layout->addWidget(components);
        pairs=table(body,"spaceradPartitionPairs",{tr("估计 A"),tr("估计 B"),tr("比较类型"),tr("差值 Gy"),tr("可作经验比较"),tr("差值 / 合成 SE")});pairs->setMinimumHeight(110);layout->addWidget(pairs);
        notice=new QLabel(body);notice->setObjectName("spaceradPartitionNotice");notice->setTextFormat(Qt::PlainText);notice->setWordWrap(true);layout->addWidget(notice);auto* exports=new QHBoxLayout;csv=new QPushButton(tr("导出研究 CSV"),body);csv->setObjectName("spaceradPartitionCsv");json=new QPushButton(tr("导出完整 JSON"),body);json->setObjectName("spaceradPartitionJson");exports->addWidget(csv);exports->addWidget(json);exports->addStretch();auto* close=new QPushButton(tr("关闭"),body);exports->addWidget(close);layout->addLayout(exports);
        service=new PartitionStudyService(this);service->configure(runtime);connect(close,&QPushButton::clicked,this,&QDialog::close);connect(fresh,&QPushButton::clicked,this,[this]{freshDirectory();});freshDirectory();
        connect(run,&QPushButton::clicked,this,[this]{try{report=nullptr;render();notice->clear();progress->setValue(0);service->start(source,scanSettings(),settings(),QFileInfo(output->text()).absoluteFilePath());}catch(const std::exception& e){notice->setText(QString::fromUtf8(e.what()));}});connect(cancel,&QPushButton::clicked,service,&PartitionStudyService::cancel);
        connect(service,&PartitionStudyService::stateChanged,this,[this](const QString& state){bool busy=service->running();editor->setEnabled(!busy);run->setEnabled(!busy);open->setEnabled(!busy);saveConfig->setEnabled(!busy);importConfig->setEnabled(!busy);cancel->setEnabled(busy&&state!="cancelling");if(state=="cancelled"||state=="failed"){report=nullptr;try{report=loadPartitionStudy(service->outputDirectory());}catch(...){}render();status->setText(state=="cancelled"?tr("已取消；保留已完成子扫描，未接收完整研究结果。"):tr("研究失败；请检查子扫描档案。"));}});
        connect(service,&PartitionStudyService::progress,this,[this](int done,int total,qint64 n,qint64 budget){progress->setValue(budget?int(1000.0*n/budget):0);status->setText(tr("完成 %1 / %2 个能段扫描；%3 / %4 历史。%5").arg(done).arg(total).arg(n).arg(budget).arg(service->outputDirectory()));});
        connect(service,&PartitionStudyService::failed,this,[this](const QString& e){notice->setText(e);});connect(service,&PartitionStudyService::completed,this,[this](const QByteArray& raw){report=Json::parse(raw.toStdString());render();progress->setValue(1000);status->setText(tr("研究完成并逐任务复核：%1 个能段扫描，%2 个靶区 / 壁厚组合。%3").arg(report.at("scans").size()).arg(report.at("rows").size()).arg(service->outputDirectory()));});
        connect(open,&QPushButton::clicked,this,[this]{QPointer<PartitionDialog> alive(this);auto dir=QFileDialog::getExistingDirectory(this,tr("选择原生桌面研究目录"));if(!alive)return;if(!dir.isEmpty())openArchive(dir);});connect(saveConfig,&QPushButton::clicked,this,[this]{exportFile(2);});connect(importConfig,&QPushButton::clicked,this,[this]{importFile();});connect(csv,&QPushButton::clicked,this,[this]{exportFile(0);});connect(json,&QPushButton::clicked,this,[this]{exportFile(1);});
        connect(estimates,&QTableWidget::currentCellChanged,this,[this](int row,int,int,int){detail(row);});connect(bands,&QTableWidget::itemChanged,this,[this]{updatePlan();});for(auto* field:{thickness,rse,confidence})connect(field,&QLineEdit::textChanged,this,[this]{updatePlan();});connect(shell,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{updatePlan();});connect(replicas,qOverload<int>(&QSpinBox::valueChanged),this,[this]{updatePlan();});connect(hits,qOverload<int>(&QSpinBox::valueChanged),this,[this]{updatePlan();});
